export const tokens = {
  colors: {
    background: '#FFFFFF',
    surface: '#F2F2F7',
    surfaceDark: '#1C1C1E',
    text: '#1C1C1E',
    textOnDark: '#F2F2F7',
    primary: '#007AFF',
    border: '#C7C7CC',
  },
  spacing: {
    sm: 8,
    md: 16,
    lg: 24,
  },
  radius: { md: 12 },
} as const;

import { View, Text, StyleSheet } from 'react-native';
import { tokens } from '../theme/tokens';

export interface ThemeCardProps {
  title: string;
  body: string;
  dark?: boolean;
}

export function ThemeCard({ title, body, dark = false }: ThemeCardProps): JSX.Element {
  const palette = dark ? tokens.colors.surfaceDark : tokens.colors.surface;
  const textColor = dark ? tokens.colors.textOnDark : tokens.colors.text;
  return (
    <View
      style={[styles.card, { backgroundColor: palette }]}
      accessibilityLabel={`${title}: ${body}`}
    >
      <Text style={[styles.title, { color: textColor }]}>{title}</Text>
      <Text style={[styles.body, { color: textColor }]}>{body}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  card: {
    borderRadius: tokens.radius.md,
    padding: tokens.spacing.md,
    margin: tokens.spacing.sm,
    borderWidth: 1,
    borderColor: tokens.colors.border,
  },
  title: { fontSize: 18, fontWeight: '700', marginBottom: tokens.spacing.sm },
  body: { fontSize: 14 },
});
